import { formatDate } from '@/utils/validate';
import { mapState } from 'vuex';
export default {
  name: 'home_time',
  cname: '时间',
  icon: 'iconbiaodanzujian-shijian',
  configName: 'c_home_time',
  type: 0, // 0 基础组件 1 营销组件 2工具组件
  defaultName: 'times', // 外面匹配名称
  props: {
    index: {
      type: null
    },
    num: {
      type: null
    }
  },
  computed: {
    ...mapState('admin/mobildConfig', ['defaultArray'])
  },
  watch: {
    pageData: {
      handler (nVal, oVal) {
        console.log('eee',nVal)
        this.setConfig(nVal)
      },
      deep: true
    },
    num: {
      handler (nVal, oVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[nVal]
        this.setConfig(data)
      },
      deep: true
    },
    'defaultArray': {
      handler (nVal, oVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[this.num]
        this.setConfig(data);
      },
      deep: true
    }
  },
  data () {
    return {
      defaultConfig: {
        name: 'times',
        timestamp: this.num,
        titleConfig: {
          title: '标题',
          value: '时间',
          place: '请输入标题',
          max: 10,
          type:'form'
        },
        valConfig: {
          title: '默认值',
          type: 'time',
          specifyDate: '',
          tabVal: 0,
          tabData: 0,
          tabList: [
            {
              name: '显示'
            },
            {
              name: '隐藏'
            }
          ],
          dataList: [
            {
              name: '当前时间'
            },
            {
              name: '指定时间'
            }
          ]
        },
        tipConfig: {
          title: '提示语',
          value: '请选择',
          place: '请输入提示语',
          max: 10,
          type:'form'
        },
        titleShow: {
          title: '是否必填',
          val: true,
          type:'form'
        },
      },
      titleTxt: '',
      tipVal: '',
      pageData: {},
      time:''
    }
  },
  mounted () {
    this.$nextTick(() => {
      this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num]
      this.setConfig(this.pageData)
    })
  },
  methods: {
    setConfig (data) {
      if(!data) return
      if(data.titleConfig){
        this.titleTxt = data.titleConfig.value
        if(data.valConfig.tabVal == 0){
          if(data.valConfig.tabData==0){
            this.tipVal = '';
            this.time = formatDate(new Date(Number(new Date().getTime())), 'hh:mm')
          }else{
            if(data.valConfig.specifyDate){
              this.tipVal = '';
              this.time = data.valConfig.specifyDate
            }else{
              this.tipVal = data.tipConfig.value
            }
          }
        }else{
          this.tipVal = data.tipConfig.value
        }
      }
    }
  }
}
